                const popover = find('[data-ds-popover]');
                if (popover) Alpine.$data(popover).dsOpen = false;
                if (!c) return;
                const digits = field.value.replace(/\D/g, '');
                choose(c);
                field.value = shown(digits);
                post(e164(digits));
                if (field.value) check();
                settle();
